import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const EVIDENCE_TYPES = ['통장', '카드', '현금영수증', '전자세금계산서'];
const STATUSES = ['기안', '결재대기', '진행중', '승인', '보류', '반려', '회수', '완료'];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function bad(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function isId(v: unknown): boolean {
  if (typeof v === 'number') {
    return Number.isInteger(v) && v > 0;
  }
  return typeof v === 'string' && /^[0-9]+$/.test(v);
}

function isPositiveNumber(v: unknown): boolean {
  if (typeof v === 'number') {
    return Number.isFinite(v) && v > 0;
  }
  if (typeof v === 'string' && v.trim() !== '') {
    return Number.isFinite(Number(v)) && Number(v) > 0;
  }
  return false;
}

function empty(v: unknown): boolean {
  return v === undefined || v === null || v === '';
}

@Controller('api/v1')
export class FnSfr00402Controller {
  @Post('/expense-resolutions')
  @HttpCode(200)
  async createExpenseResolution(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '예산·회계 담당자');
    const data = checks.inputOf(req.body);
    if (typeof data.resolutionDate !== 'string' || !/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(data.resolutionDate)) {
      throw bad('결의일자를 YYYY-MM-DD 형식으로 입력하세요.');
    }
    if (!isId(data.projectId)) {
      throw bad('프로젝트를 선택하세요.');
    }
    if (!isId(data.budgetItemId)) {
      throw bad('예산과목을 선택하세요.');
    }
    if (!isId(data.departmentId)) {
      throw bad('결의부서를 선택하세요.');
    }
    if (!isPositiveNumber(data.amount)) {
      throw bad('결의 금액은 0보다 큰 숫자여야 합니다.');
    }
    if (typeof data.evidenceType !== 'string' || !EVIDENCE_TYPES.includes(data.evidenceType)) {
      throw bad('증빙 유형을 선택하세요.');
    }
    if (!empty(data.purchaseRequestId) && !isId(data.purchaseRequestId)) {
      throw bad('연결 품의서 값이 올바르지 않습니다.');
    }
    if (!empty(data.partnerId) && !isId(data.partnerId)) {
      throw bad('거래처 값이 올바르지 않습니다.');
    }
    const purchaseRequestId = empty(data.purchaseRequestId) ? null : Number(data.purchaseRequestId);
    const partnerId = empty(data.partnerId) ? null : Number(data.partnerId);

    return transaction(async (db) => {
      const projects = await db.query(
        'SELECT project_id FROM project WHERE project_id = CAST(:id AS bigint)',
        { id: Number(data.projectId) },
      );
      if (projects.length === 0) {
        throw new ApiError(404, 'NOT_FOUND', '프로젝트를 찾을 수 없습니다.');
      }
      const items = await db.query(
        'SELECT budget_item_id FROM budget_item WHERE budget_item_id = CAST(:id AS bigint)',
        { id: Number(data.budgetItemId) },
      );
      if (items.length === 0) {
        throw new ApiError(404, 'NOT_FOUND', '예산과목을 찾을 수 없습니다.');
      }
      const departments = await db.query(
        'SELECT department_id FROM department WHERE department_id = CAST(:id AS bigint)',
        { id: Number(data.departmentId) },
      );
      if (departments.length === 0) {
        throw new ApiError(404, 'NOT_FOUND', '결의부서를 찾을 수 없습니다.');
      }
      if (partnerId !== null) {
        const partners = await db.query(
          'SELECT partner_id FROM partner WHERE partner_id = CAST(:id AS bigint)',
          { id: partnerId },
        );
        if (partners.length === 0) {
          throw new ApiError(404, 'NOT_FOUND', '거래처를 찾을 수 없습니다.');
        }
      }
      if (purchaseRequestId !== null) {
        const purchases = await db.query(
          'SELECT amount AS "amount" FROM purchase_request WHERE purchase_request_id = CAST(:id AS bigint)',
          { id: purchaseRequestId },
        );
        if (purchases.length === 0) {
          throw new ApiError(404, 'NOT_FOUND', '연결 품의서를 찾을 수 없습니다.');
        }
        if (Number(data.amount) > Number(purchases[0].amount)) {
          throw new ApiError(422, 'AMOUNT_EXCEEDS_PURCHASE_REQUEST', '결의 금액이 연결 품의 금액을 초과합니다.');
        }
      }
      const inserted = await db.query(
        'INSERT INTO expense_resolution (resolution_date, department_id, author_id, resolution_type, project_id, budget_item_id, partner_id, purchase_request_id, amount, evidence_type, approval_status, created_at, updated_at) ' +
          'VALUES (CAST(:resolutionDate AS date), CAST(:departmentId AS bigint), CAST(:userId AS bigint), \'지출\', CAST(:projectId AS bigint), CAST(:budgetItemId AS bigint), CAST(:partnerId AS bigint), CAST(:purchaseRequestId AS bigint), CAST(:amount AS numeric), :evidenceType, \'기안\', now(), now()) ' +
          'RETURNING expense_resolution_id AS "expenseResolutionId"',
        {
          resolutionDate: data.resolutionDate,
          departmentId: Number(data.departmentId),
          userId: user.id,
          projectId: Number(data.projectId),
          budgetItemId: Number(data.budgetItemId),
          partnerId,
          purchaseRequestId,
          amount: String(data.amount),
          evidenceType: data.evidenceType,
        },
      );
      // 가정: 문서번호는 ER-날짜-ID 6자리로 자동 부여한다 (채번 규칙 미확정)
      const rows = await db.query(
        'UPDATE expense_resolution SET document_no = \'ER-\' || to_char(now(), \'YYYYMMDD\') || \'-\' || lpad(expense_resolution_id::text, 6, \'0\'), updated_at = now() ' +
          'WHERE expense_resolution_id = CAST(:id AS bigint) ' +
          'RETURNING expense_resolution_id AS "expenseResolutionId", document_no AS "documentNo", approval_status AS "approvalStatus"',
        { id: Number(inserted[0].expenseResolutionId) },
      );
      return rows[0];
    });
  }

  @Get('/expense-resolutions')
  async listExpenseResolutions(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '예산·회계 담당자');
    const q = checks.queryOf(req.query);
    const page = empty(q.page) ? 0 : Number(q.page);
    const size = empty(q.size) ? DEFAULT_SIZE : Number(q.size);
    if (!Number.isInteger(page) || page < 0) {
      throw bad('page는 0 이상의 정수여야 합니다.');
    }
    if (!Number.isInteger(size) || size < 1 || size > MAX_SIZE) {
      throw bad('size는 1 이상 200 이하의 정수여야 합니다.');
    }
    if (!empty(q.projectId) && !isId(q.projectId)) {
      throw bad('프로젝트 값이 올바르지 않습니다.');
    }
    if (!empty(q.approvalStatus) && !STATUSES.includes(String(q.approvalStatus))) {
      throw bad('결재 상태 값이 올바르지 않습니다.');
    }
    const params = {
      projectId: empty(q.projectId) ? null : Number(q.projectId),
      approvalStatus: empty(q.approvalStatus) ? null : String(q.approvalStatus),
    };
    const where =
      ' WHERE (CAST(:projectId AS bigint) IS NULL OR project_id = CAST(:projectId AS bigint))' +
      ' AND (CAST(:approvalStatus AS text) IS NULL OR approval_status = CAST(:approvalStatus AS text))';

    return transaction(async (db) => {
      const totals = await db.query('SELECT COUNT(*) AS "total" FROM expense_resolution' + where, params);
      const items = await db.query(
        'SELECT expense_resolution_id AS "expenseResolutionId", document_no AS "documentNo", resolution_date AS "resolutionDate", amount AS "amount", approval_status AS "approvalStatus" ' +
          'FROM expense_resolution' +
          where +
          ' ORDER BY expense_resolution_id DESC LIMIT CAST(:limit AS int) OFFSET CAST(:offset AS int)',
        { ...params, limit: size, offset: page * size },
      );
      return { items, page, size, total: Number(totals[0].total) };
    });
  }

  @Post('/expense-resolutions/:expenseResolutionId/submit')
  @HttpCode(200)
  async submitExpenseResolution(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const id = req.params['expenseResolutionId'];
    if (!isId(id)) {
      throw bad('결의서 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT approval_status AS "approvalStatus", department_id AS "departmentId", document_no AS "documentNo" FROM expense_resolution WHERE expense_resolution_id = CAST(:id AS bigint) FOR UPDATE',
        { id: Number(id) },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'EXPENSE_RESOLUTION_NOT_FOUND', '결의서를 찾을 수 없습니다.');
      }
      const row = found[0];
      // 가정: 상신은 기안 상태에서만 가능하다 (전환표에 다른 출발 상태 없음)
      if (row.approvalStatus !== '기안') {
        throw new ApiError(409, 'EXPENSE_RESOLUTION_STATUS_CONFLICT', '상신할 수 있는 상태가 아닙니다.');
      }
      // 가정: 결재양식은 사용 중인 연계 결재 양식 중 첫 번째를 쓴다
      const forms = await db.query(
        'SELECT approval_form_id AS "approvalFormId" FROM approval_form WHERE use_status = \'사용\' AND is_linked_approval = true ORDER BY approval_form_id LIMIT 1',
        {},
      );
      if (forms.length === 0) {
        throw new ApiError(502, 'APPROVAL_LINKAGE_FAILED', '전자결재 연계에 실패했습니다. 사용 가능한 결재 양식이 없습니다.');
      }
      // 가정: 결재문서 번호는 결의서 문서번호 앞에 AP-를 붙여 만든다
      const docs = await db.query(
        'INSERT INTO approval_document (approval_form_id, drafter_id, drafter_department_id, document_number, title, approval_status, is_urgent, is_secret, linked_business_type, linked_business_id, submitted_at, created_at, updated_at) ' +
          'VALUES (CAST(:formId AS bigint), CAST(:userId AS bigint), CAST(:departmentId AS bigint), \'AP-\' || :documentNo, \'결의서 \' || :documentNo, \'결재대기\', false, false, \'expense_resolution\', CAST(:id AS bigint), now(), now(), now()) ' +
          'RETURNING approval_document_id AS "approvalDocumentId"',
        {
          formId: Number(forms[0].approvalFormId),
          userId: user.id,
          departmentId: Number(row.departmentId),
          documentNo: String(row.documentNo ?? id),
          id: Number(id),
        },
      );
      const updated = await db.query(
        'UPDATE expense_resolution SET approval_status = \'결재대기\', approval_document_id = CAST(:docId AS bigint), updated_at = now() ' +
          'WHERE expense_resolution_id = CAST(:id AS bigint) RETURNING approval_status AS "approvalStatus"',
        { docId: Number(docs[0].approvalDocumentId), id: Number(id) },
      );
      return updated[0];
    });
  }
}

