import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  Field,
  Filters,
  Form,
  LookupSelect,
  Num,
  NumberInput,
  Pager,
  Pairs,
  Select,
  Tiles,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const STATUS_OPTIONS: [string, string][] = ['기안', '결재대기', '진행중', '승인', '보류', '반려', '회수', '완료'].map((s) => [s, s]);
const EVIDENCE_OPTIONS: [string, string][] = ['통장', '카드', '현금영수증', '전자세금계산서'].map((s) => [s, s]);
const SIZE = 20;

function BudgetStatus({ role, projectId, budgetItemId }: { role: string; projectId: unknown; budgetItemId: unknown }) {
  const { data, error } = useData<Page | undefined>(
    () => {
      if (!projectId) {
        return Promise.resolve(undefined);
      }
      return call<Page>('GET', '/budget-statuses', role, undefined, { projectId, budgetItemId });
    },
    [projectId, budgetItemId],
  );
  if (!projectId) {
    return <p>프로젝트를 선택하면 예산 현황이 보입니다.</p>;
  }
  if (error) {
    return <p>{error}</p>;
  }
  const row = data && data.items.length > 0 ? data.items[0] : undefined;
  if (!row) {
    return <p>예산 현황이 없습니다.</p>;
  }
  return (
    <Tiles
      items={[
        ['실행예산액', <Num value={row.execBudgetAmount} />],
        ['이월예산액', <Num value={row.carryoverAmount} />],
        ['예산총액', <Num value={row.totalBudgetAmount} />],
        ['집행액', <Num value={row.executedAmount} />],
        ['예산잔액', <Num value={row.balanceAmount} />],
      ]}
    />
  );
}

function CreateForm({ role, onDone }: { role: string; onDone: () => void }) {
  const [form, setForm] = useState<Row>({});
  const set = (key: string, value: unknown) => setForm({ ...form, [key]: value });

  async function submit() {
    const missing: string[] = [];
    if (!form.resolutionDate) missing.push('결의일자');
    if (!form.projectId) missing.push('프로젝트');
    if (!form.budgetItemId) missing.push('예산과목');
    if (form.amount === undefined || form.amount === '') missing.push('결의 금액');
    if (!form.evidenceType) missing.push('증빙 유형');
    if (!form.departmentId) missing.push('결의부서');
    if (missing.length > 0) {
      throw new Error('필수 항목을 입력하세요: ' + missing.join(', '));
    }
    await call('POST', '/expense-resolutions', role, {
      resolutionDate: form.resolutionDate,
      purchaseRequestId: form.purchaseRequestId || undefined,
      projectId: form.projectId,
      budgetItemId: form.budgetItemId,
      amount: form.amount,
      evidenceType: form.evidenceType,
      partnerId: form.partnerId || undefined,
      departmentId: form.departmentId,
    });
    onDone();
  }

  return (
    <Form onSubmit={submit} submit="저장">
      <Field label="결의일자" required>
        <DateInput value={form.resolutionDate} onChange={(v) => set('resolutionDate', v)} />
      </Field>
      <Field label="결의부서" required>
        <LookupSelect table="department" role={role} value={form.departmentId} onChange={(v) => set('departmentId', v)} />
      </Field>
      <Field label="프로젝트" required>
        <LookupSelect table="project" role={role} value={form.projectId} onChange={(v) => set('projectId', v)} />
      </Field>
      <Field label="예산과목" required>
        <LookupSelect table="budget_item" role={role} value={form.budgetItemId} onChange={(v) => set('budgetItemId', v)} />
      </Field>
      <Field label="예산 현황" wide>
        <BudgetStatus role={role} projectId={form.projectId} budgetItemId={form.budgetItemId} />
      </Field>
      <Field label="연결 품의서">
        <LookupSelect table="purchase_request" role={role} value={form.purchaseRequestId} onChange={(v) => set('purchaseRequestId', v)} />
      </Field>
      <Field label="결의 금액" required>
        <NumberInput value={form.amount} onChange={(v) => set('amount', v)} />
      </Field>
      <Field label="증빙 유형" required>
        <Select value={form.evidenceType} onChange={(v) => set('evidenceType', v)} options={EVIDENCE_OPTIONS} />
      </Field>
      <Field label="거래처">
        <LookupSelect table="partner" role={role} value={form.partnerId} onChange={(v) => set('partnerId', v)} />
      </Field>
    </Form>
  );
}

export default function FnSfr00402Page({ role, notify }: PageProps) {
  const [projectId, setProjectId] = useState<unknown>('');
  const [status, setStatus] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [creating, setCreating] = useState(false);
  const [detail, setDetail] = useState<Row | null>(null);
  const [target, setTarget] = useState<Row | null>(null);

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/expense-resolutions', role, undefined, { ...applied, page, size: SIZE }),
    [applied, page, role],
  );
  const rows = data ? data.items : [];
  const drafts = rows.filter((r) => r.approvalStatus === '기안');
  const draftTotal = drafts.reduce((sum, r) => sum + Number(r.amount ?? 0), 0);

  function search() {
    setPage(0);
    setApplied({ projectId, approvalStatus: status });
  }

  function reset() {
    setProjectId('');
    setStatus('');
    setPage(0);
    setApplied({});
  }

  async function submitTarget() {
    if (!target) {
      return;
    }
    await call('POST', '/expense-resolutions/' + target.expenseResolutionId + '/submit', role, {});
    notify('결재를 상신했습니다.');
    setTarget(null);
    reload();
  }

  return (
    <div className="bento">
      <section className="box span-8">
        <h2>결의 목록</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="프로젝트">
            <LookupSelect table="project" role={role} value={projectId} onChange={(v) => setProjectId(v)} />
          </Field>
          <Field label="결재 상태">
            <Select value={status} onChange={setStatus} options={STATUS_OPTIONS} />
          </Field>
        </Filters>
        <Band total={data ? data.total : 0}>
          <button type="button" onClick={() => setCreating(true)}>결의서 등록</button>
        </Band>
        {error ? <p>{error}</p> : null}
        <DataTable
          rows={rows}
          onRowClick={(row) => setDetail(row)}
          empty="결의서가 없습니다."
          columns={[
            { key: 'documentNo', label: '문서번호' },
            { key: 'resolutionDate', label: '결의일자', render: (r) => <DateText value={r.resolutionDate} /> },
            { key: 'amount', label: '결의 금액', render: (r) => <Num value={r.amount} /> },
            { key: 'approvalStatus', label: '결재 상태', render: (r) => <Badge value={r.approvalStatus} /> },
            {
              key: 'action',
              label: '처리',
              render: (r) =>
                r.approvalStatus === '기안' ? (
                  <button
                    type="button"
                    onClick={(e) => {
                      e.stopPropagation();
                      setTarget(r);
                    }}
                  >
                    상신
                  </button>
                ) : null,
            },
          ]}
        />
        <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
      </section>
      <section className="box span-4">
        <h2>상신 대기</h2>
        <Tiles
          items={[
            ['기안 건수', <Num value={drafts.length} />],
            ['기안 금액', <Num value={draftTotal} />],
          ]}
        />
      </section>
      {creating ? (
        <Drawer title="결의서 등록" onClose={() => setCreating(false)}>
          <CreateForm
            role={role}
            onDone={() => {
              notify('결의서를 등록했습니다.');
              setCreating(false);
              reload();
            }}
          />
        </Drawer>
      ) : null}
      {detail ? (
        <Drawer title="결의서 상세" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['문서번호', String(detail.documentNo ?? '')],
              ['결의일자', <DateText value={detail.resolutionDate} />],
              ['결의 금액', <Num value={detail.amount} />],
              ['결재 상태', <Badge value={detail.approvalStatus} />],
            ]}
          />
        </Drawer>
      ) : null}
      {target ? (
        <Drawer title="결재 상신" onClose={() => setTarget(null)}>
          <Form onSubmit={submitTarget} submit="상신" note={'문서번호 ' + String(target.documentNo ?? '') + ' 결의서를 전자결재로 상신합니다.'} />
        </Drawer>
      ) : null}
    </div>
  );
}
